  '{cause} — init refuses on it': '{cause} — на этом init откажет',
  'backslop agent hook records for {harness} sit here, behind the symlink {link}, and the hooks field of {config} does not select {harness} — init does not remove records through a link: remove them by hand': 'здесь, за символической ссылкой {link}, записи хуков агента backslop для {harness}, а поле hooks в {config} {harness} не выбирает — сквозь ссылку init записи не снимает: удали их вручную',
  'backslop agent hook records for {harness} sit here, but the hooks field of {config} does not select {harness} — run {cli} init': 'здесь записи хуков агента backslop для {harness}, а поле hooks в {config} {harness} не выбирает — запусти {cli} init',
  'the agent hook record “{command}” runs another cli than this project’s {cli} — run {cli} init': 'запись хука агента «{command}» запускает не cli этого проекта {cli} — запусти {cli} init',
  'the agent hook records of {harness} differ from what init writes: a duplicate or a record under another event — run {cli} init': 'записи хуков агента для {harness} расходятся с тем, что пишет init: дубль или запись под другим событием — запусти {cli} init',
  'the {key} agent hook record of {harness} is missing: expected “{command}” — run {cli} init': 'нет записи хука агента {key} для {harness}: ожидается «{command}» — запусти {cli} init',
  // lib/init.js
  'init cannot lay out the skeleton in it': 'init не разложит в нём скелет',
  '--dir “{dir}”: expected a relative path inside the project': '--dir «{dir}»: нужен относительный путь внутри проекта',
  '{config} already sets {key} = “{value}”; change it in the config, not with this flag': '{config} уже есть, и там {key} = «{value}»; менять — правкой конфига, не флагом',
  '--prefix “{prefix}”: expected 2–6 uppercase Latin letters or digits, starting with a letter': '--prefix «{prefix}»: нужны 2–6 заглавных латинских букв или цифр, первая буква',
  '--cli must be a non-empty command string': '--cli — непустая строка команды',
  '--tools {tools}: {root} is the backslop repository itself (templates/ is the running tool\'s directory), adapter outputs are not laid out here; set up a stand in a directory of its own and run init --tools {tools} there': '--tools {tools}: {root} — репозиторий самого backslop (templates/ — каталог запущенного инструмента), adapter outputs здесь не раскладываются; стенд поднимай в своём каталоге: init --tools {tools} оттуда',
  '{rel} is not a file: init reads it as the documentation index': '{rel} — не файл: init читает его как индекс документации',
  'probe is not declared in {config}: the block carries no mutation-probe requirement and the skill asks for a hand-made check without a command — declare the command in probe or describe the probe in a section of your own outside the block': 'probe в {config} не объявлен: блок не требует мутационной пробы, а скилл просит ручную проверку без команды — объяви команду полем probe или опиши пробу своим разделом вне блока',
  '{docs}/README.md already existed: link {adrRel} from it (a row in its table is the usual place), otherwise lint fails': '{docs}/README.md уже был: добавь в него ссылку на {adrRel} (обычно строкой таблицы), иначе lint красный',
  'init: {docs}/ (prefix {prefix}), files created {created}, left unchanged {skipped}': 'init: {docs}/ (префикс {prefix}), создано файлов {created}, оставлено как есть {skipped}',
  'AGENTS.md: backslop block {agentsState}; CLAUDE.md: {state}; .gitignore: {ignoreState}': 'AGENTS.md: блок backslop {agentsState}; CLAUDE.md: {state}; .gitignore: {ignoreState}',
  'cli is pinned to v{pin}, but layout was generated by v{version}: run {cli} upgrade or update cli in {config}': 'пин в cli — v{pin}, а раскладку сделала v{version}: запусти {cli} upgrade или поправь cli в {config}',
  'backslop is no longer in package.json devDependencies: restore it or change cli in {config} before rerunning init': 'backslop больше нет в devDependencies файла package.json: верни зависимость или измени cli в {config} перед повторным init',
  'backslop is not in package.json devDependencies: add it or choose another --cli before init --hooks': 'backslop нет в devDependencies файла package.json: добавь зависимость или выбери другой --cli перед init --hooks',
  'backslop is not in package.json devDependencies: restore it or change cli in {config} before upgrade': 'backslop нет в devDependencies файла package.json: верни зависимость или измени cli в {config} перед upgrade',
  'backslop is declared in package.json but is not installed: run npm install before using the agent hooks': 'backslop объявлен в package.json, но не установлен: выполни npm install перед использованием хуков агента',
  'installed backslop v{installed} is older than tool v{version}; update the declared backslop dependency ({spec}) to v{version} and run npm install': 'установлен backslop v{installed}, он старше версии инструмента v{version}; обнови объявленную зависимость backslop ({spec}) до v{version} и выполни npm install',
  'installed backslop v{installed} is newer than tool v{version}; run init with the installed version or update cli to select it': 'установлен backslop v{installed}, он новее версии инструмента v{version}; запусти init установленной версией или измени cli, чтобы выбрать её',
  'installed backslop version {installed} cannot be compared with tool v{version}; inspect the local package': 'версию установленного backslop {installed} нельзя сравнить с версией инструмента v{version}; проверь локальный пакет',
  'an unpinned cli fetches a fresh version on every run: run {cli} upgrade to pin v{version}': 'cli без пина тянет свежую версию при каждом запуске: запусти {cli} upgrade, он поставит пин v{version}',
  'next: {cli} lint validates the layout; use the backslop-seed skill to populate docs; update with {cli} upgrade': 'дальше: {cli} lint — проверка скелета; наполнение — скилл backslop-seed («заполни docs по backslop»); обновление — {cli} upgrade',
  'next: {cli} lint validates the layout; update with {cli} upgrade': 'дальше: {cli} lint — проверка скелета; обновление — {cli} upgrade',
  'next: {cli} lint validates the layout; an adapter installs the skills, including the one that populates docs: {cli} init --tools claude|cursor|codex; update with {cli} upgrade': 'дальше: {cli} lint — проверка скелета; скиллы, и с ними наполнение docs, ставит adapter: {cli} init --tools claude|cursor|codex; обновление — {cli} upgrade',
